import subprocess
import psutil
import time
def task_func(process_name: str) -> str:
    process_found = False
    for proc in psutil.process_iter(['name']):
        try:
            if proc.info['name'] == process_name:
                proc.terminate()
                process_found = True
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            continue

    if process_found:
        time.sleep(1)
        subprocess.Popen(process_name, shell=True)
        return f"Process found. Restarting {process_name}."
    else:
        subprocess.Popen(process_name, shell=True)
        return f"Process not found. Starting {process_name}."

import subprocess
import os
import random
def task_func(directory, file_list):
    if not file_list:
        return None

    selected_file = random.choice(file_list)
    file_path = os.path.join(directory, selected_file)

    process = subprocess.Popen(file_path, shell=True)
    return process.poll()

import subprocess
import platform
import time
def task_func(url):
    system = platform.system()
    if system == 'Windows':
        command = f'start {url}'
    elif system == 'Darwin':
        command = f'open {url}'
    else:
        command = f'xdg-open {url}'

    process = subprocess.Popen(command, shell=True)
    time.sleep(1)

    return process.poll()
